function minify(css){
  return String(css)
    .replace(/\/\*[\s\S]*?\*\//g,'')
    .replace(/\s+/g,' ')
    .replace(/\s*([{}:;,>])\s*/g,'$1')
    .replace(/;}/g,'}')
    .trim();
}
var EXPORTS={minify:minify};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CssForgePure = EXPORTS; }
